Een closure is een functie die toegang behoudt tot variabelen uit de scope waar hij gemaakt is — ook nadat die scope verdwenen is.

Voorbeeld:
function makeCounter() {
  let count = 0;
  return {
    increment: () => ++count,
    value: () => count
  };
}
const counter = makeCounter();
counter.increment(); // 1
counter.increment(); // 2
// 'count' is nergens anders bereikbaar — encapsulation

Factory functies:
function multiply(factor: number) {
  return (n: number) => n * factor; // closure over 'factor'
}
const double = multiply(2);
double(5); // 10

